function step(dt){s.raidAlert=Math.max(0,s.raidAlert-dt);s.shake=Math.max(0,s.shake-dt*7);s.cursorCd=Math.max(0,s.cursorCd-dt);if(s.between>0){s.between-=dt;if(s.between<=0){s.waveTime=0;s.next=.1;beep(180,.16)}}else{let duration=s.stage.duration,count=4+s.wave*2+s.stage.extraEnemies;s.waveTime+=dt;if(s.waveTime<duration&&s.waveTime>=s.next){spawn();s.next+=duration/count*rnd(.75,1.05)}if(s.beastsSent<s.stage.tier&&s.waveTime>=6+s.beastsSent*5)spawnAnimal();if(s.waveTime>=duration&&!s.enemies.length){if(s.wave>=s.stage.waves){win();return}s.wave++;s.beastsSent=0;s.between=s.stage.rest;s.gold+=20;s.wood+=16;text(640,285,'波次守住！ +20矿 +16木','#f6d66d');beep(760,.18)}}action(dt);units(dt);enemies(dt);effects(dt);sync()}
